export function chapterSummaries(result){
 const base=result.code.split('-')[0];
 if(typeStories[base]&&!result.dimensions.slice(0,4).some(d=>d.boundary))return Object.fromEntries(['traits','work','growth','relations'].map(chapter=>[chapter,chapter==='traits'?(typeCopyText(base)||independentTypeSummary(base,chapter,result.dimensions)):independentTypeSummary(base,chapter,result.dimensions)]));
 const [e,n,t,j,a]=result.dimensions;
 const pick=(axis,left,right,middle)=>axis.boundary?middle:axis.letter===axis.letters[0]?left:right;
 const traits=pick(e,'你常在与人交流时逐渐理清自己的想法，对外界的回应和新的互动保持兴趣。','你更习惯先在心里把事情想清楚，再选择合适的人交流；安静和独立思考能让你找回自己的节奏。','独处与交流在这次作答中没有明显分出高下，你的投入程度可能更取决于话题与相处对象。')+pick(n,'遇到新问题时，你容易先看到背后的关联与尚未实现的可能，愿意追问熟悉答案之外还有什么解释。','遇到新问题时，你更愿意从事实和已有经验出发，用具体的观察判断一个想法是否站得住脚。','理解问题时，你既会关注具体事实，也会考虑整体方向，需要结合情境判断哪种方式更有帮助。')+pick(t,'这与重视逻辑和一致标准的习惯相结合，使你倾向于先检验结论，再决定是否接受它。','与此同时，你也会把人的感受和处境带进判断，希望好的决定能兼顾参与者的需要。','在规则与感受之间，你的得分接近中点，实际取舍未必能由一个固定字母概括。')+pick(j,'你希望把理解转化成清楚的安排，不过也需要给新信息留出修改计划的空间。','你喜欢为探索保留余地，但有时也可能因为还想多看一种可能，而推迟最终定案。','你对计划和弹性的偏好不明显，可以观察自己在不同任务中的真实节奏。');
 const work=pick(n,'工作中，能提出问题、理解复杂关系并尝试新方法的任务，可能比单纯重复既有流程更容易吸引你。','工作中，目标具体、资源清楚并能看到实际成果的任务，可能更容易让你感到自己的投入有了落点。','工作中，你可能同时需要方向感和可操作的步骤；与其按类型挑选职位，不如观察具体任务是否让你投入。')+pick(t,'你往往在意方案是否合理、标准是否一致，也愿意指出还没有被解决的关键问题。','你往往在意工作的意义及其对人的影响，也容易注意到团队合作里没有说出口的需要。','做判断时，你可能在效率和人的处境之间权衡，清楚的目标与沟通期待会有帮助。')+pick(e,'通过讨论、反馈和共同推进，你能较快发现思路中的遗漏；同时也要留出独立整理的时间。','能够独立准备、减少临时打断的环境有利于你深入思考，但值得在想法还未完善时就让同伴看见进展。','独立处理和共同讨论都可以尝试，关键是找到适合任务的沟通频率。')+pick(j,'明确分工和把事情做好并交出去节点有助于发挥你的条理，变化出现时，及时重新协商比勉强守住旧计划更有效。','探索空间有助于发挥你的灵活性，而明确的阶段目标能帮助你把有价值的想法真正把事情做好并交出去出去。','分工与把事情做好并交出去预期仍需要说清楚，至于过程安排，可以根据任务保留调整空间。');
 const growth=pick(a,'面对不确定或不理想的反馈，你通常比较容易把注意力放回下一步行动，这有助于维持节奏，却也可能让你忽略已经累积的疲劳。','你对评价和不确定较为留意，常会回头检查自己哪里还能做得更好。这能带来细致的改进，也可能让一次普通的失误占据过多注意力。','这次作答没有显示明确的压力反应偏向；与其急着给自己定性，不如观察哪些情境会让你反复担心，哪些情境下又能较快恢复。')+pick(j,'习惯提前安排的你，可以练习把“必须按原计划完成”改成“根据新证据及时调整”，让结构成为支持而非束缚。','习惯保留选择的你，可以练习为一次探索设定结束时间，接受先完成一个可用版本，再通过反馈继续完善。','无论偏好计划还是灵活，给任务设置检查点都能帮助你判断何时坚持、何时调整。')+'成长不必从改变所有习惯开始。选一件最近真正困扰你的事，区分可观察的事实、自己的解释和能够采取的行动，再做一个小而具体的尝试。回头看看时关注方法是否有效，而不把一次结果当成对整个人的评价。';
 const relations=pick(e,'在人际关系中，你可能通过主动分享和持续互动表达亲近，也希望从对方的回应中感受到连接。','在人际关系中，你可能更重视少数深入的连接，也需要一些独处时间整理感受。安静并不意味着疏远，但对方未必能自动理解你的节奏。','在人际关系中，你可能既享受交流，也需要独处；把当下的需要说清楚，比依赖一个固定标签更有帮助。')+pick(t,'遇到分歧或倾诉时，你容易先分析原因、寻找办法，这份解决问题的用心值得保留，不过对方有时更需要先被倾听。','你会留意表达是否让对方舒服，也愿意照顾关系中的感受，不过为了维持和气而省略自己的需要，反而可能让误解慢慢累积。','你可能在分析问题和回应感受之间来回权衡，直接询问对方想被倾听还是一起找办法，会减少猜测。')+pick(j,'你对约定和可预期的安排比较在意，可以说明哪些承诺很重要，同时给临时变化留出协商余地。','你喜欢自然、开放的相处方式，也需要让对方知道哪些事情已经确定，避免把自己的弹性变成对方的不安。','对约定的期待可以逐件协商，不必假设双方天然拥有相同标准。')+'关系中的差异未必需要消除；把具体的事实、感受和请求分开表达，往往比判断谁的性格更合适更有用。';
 const traitsDepth=pick(n,'这份对可能性的关注，也会让你在已经有了答案时继续追问：事情能否有另一种解释，眼前的方法是不是还有改进余地。','这份对实际情况的关注，也会让你在别人忙着描绘愿景时，留意那些真正决定结果的条件：资源是否足够，细节是否可靠，承诺能否兑现。','不过，同一个人在熟悉与陌生的环境中，可能采用不同的方式理解事情；中间得分不等于没有特点，也可能意味着不同经历在答案中留下了不同方向的痕迹。')+pick(t,'不过，当注意力集中在问题和推理上时，你可能低估表达方式对他人的影响。你眼中的认真求证，有时会被听成不信任；你觉得只是指出漏洞，对方却可能认为自己的努力没有得到认可。','不过，当你努力兼顾每个人的需要时，也可能发现自己的判断变得犹豫。你明白什么对自己重要，却不一定愿意让别人失望，于是把本来可以讨论的分歧留给自己慢慢消化。','规则、感受、独立与合作并不是只能选一边的事情；具体任务和关系往往比一个类型名称更能解释你的选择。')+'认识自己的价值，在于看清这些偏好何时成为助力、何时又限制了选择。保留你的自然节奏，也为不熟悉的做法留一点空间，你就更容易把理解自己变成真正有用的改变。';
 const workDepth=pick(n,'但持续的新鲜感和深入钻研，并不总能与工作的日常安排同步。一个很有吸引力的想法，也需要有人把它写清楚、验证过、把事情做好并交出去出去；如果兴趣总被下一个问题吸引，先前的积累就可能停留在尚未完成的构想里。','但可靠地完成事情，也可能让你逐渐承担过多重复性工作。当熟悉的流程变成唯一的作出判断的理由，你或许会花力气把事情做得更稳，却较少有机会重新考虑它是否还值得这样做。','但不论哪一种任务让你投入，工作里都会存在不那么有趣的环节。真正需要留意的，是这些环节只是必要的收尾，还是已经长期挤占了你最想投入的部分。')+pick(j,'你对进度和标准的重视能够让伙伴安心，然而当目标改变、信息不足时，过早确定路径也会增加返工的成本。','你对弹性的重视能够带来新的解法，然而当伙伴需要明确承诺时，过迟作出决定也会让合作变得吃力。','你对计划与弹性的得分接近中点，值得用真实项目观察自己何时需要结构、何时又需要更多自己作选择的余地。')+'因此，选择职业时不妨把目光放到岗位的实际内容：是否能持续学习，是否有足够的自主权，沟通与评价方式是否清楚。先通过一个小项目或一次真实协作检验这些条件，会比只凭职位名称判断更接近你想要的工作生活。';
 const growthDepth=pick(a,'你不必为了证明自己能够应付一切，而等到精力耗尽才允许休息。有些压力并不会立刻变成明显的不安，而是表现为注意力变散、对熟悉的事情失去耐心，或越来越难从完成任务中获得满足。','当你反复回想一次谈话、一条评价或一个没有达到预期的结果时，认真与自我苛责之间的界线可能会变得模糊。继续检查有时能发现问题，有时却只是暂时缓解不安，让你更难相信自己已经做了足够的准备。','无论你通常平稳还是偶尔敏感，压力都可能先表现为生活节奏的细微变化：睡得更晚、难以集中注意力，或对原本喜欢的事情缺少耐心。')+'给自己设置一个明确的停止点，会让改进和恢复都更有位置。完成必要的检查后，把尚不能确定的问题记下来，允许它等到获得新信息时再处理。成长也包括向人求助、接受反馈，以及在方法不合适时重新选择，而不是要求自己始终保持同一种状态。';
 const relationsDepth=pick(e,'你希望互动有来有往，但对方回应较慢时，也未必意味着热情减少。有些人需要先独自想清楚，才能认真表达；留出这段时间，往往能让之后的沟通更深入。','你习惯在自己的空间里整理想法，但沉默有时会让亲近的人不知道该靠近还是退开。简单地告诉对方“我需要一点时间，晚些时候会再聊”，既能保护独处的需要，也能让关系保持连接。','你可以在想分享的时候主动靠近，也可以在疲惫时提出暂停；重要的是让对方理解变化的原因，而不是独自猜测。')+pick(t,'当对方谈起难处时，不妨先问一句：你现在想让我陪你说说，还是一起想办法？这不会削弱解决问题的能力，反而能让你的建议在对方准备好时真正发挥作用。','当你不赞同或已经感到疲惫时，也可以直接说出限制。坦诚并不等于冷漠，一次温和而清楚的拒绝，往往比长期勉强配合更能保护双方的信任。','同样，在分歧中直接确认彼此的期待，也比推测对方的动机更有帮助。')+'一段让人安心的关系，通常不是双方从不发生冲突，而是在需要不一致时仍然愿意解释、倾听和重新协商。';
 const traitsScene=pick(n,'比如，接触一个陌生领域时，你可能不会满足于记住现成的步骤，而是想弄明白它为什么这样运作、与其他事物有什么联系。一段有启发性的谈话、一个尚未解释的现象，甚至一个看似不合理的规定，都可能引出后续的思考。你未必会立即把每个想法付诸行动，但这种不断建立联系的过程，本身就可能带来满足。','比如，接触一个陌生领域时，你可能会先找一份清楚的示例，观察熟悉这件事的人怎样操作，再通过亲自尝试形成判断。比起听到一个宏大的结论，你更想知道它具体改变了什么、需要哪些条件、遇到问题应该怎样处理。能够把模糊的问题逐步变得清楚，会让你感到踏实。','比如，同一个陌生领域，如果需要快速上手，你可能偏向具体示例；如果需要决定方向，你又会转向整体框架。这种变化值得被记录，而不是急着把它归结为性格不稳定。')+pick(e,'当你把这些发现分享出去时，讨论往往又会带来新的线索。你可能通过解释、提问和接住别人的反应，逐渐确定自己究竟相信什么。','即使表面上没有太多表达，你的思考也未必停了下来。有时你已经在心里比较了几种解释，只是还没有找到愿意说出口的版本。','至于这些发现是先说出来还是独自整理，你可以按对象、精力和任务选择方式，不必要求自己始终如一。');
 const traitsTension=pick(j,'当事情悬而未决时，你可能更想尽快确定一个方向，因为明确的下一步能够减少消耗。但某些问题确实需要多等一轮反馈，才会出现值得依赖的答案。让计划拥有检查点，而不把它当成不可修改的承诺，会帮助你既保有秩序，也不丢掉新的机会。','你可能享受一个问题逐渐展开的过程，却不太喜欢它被过早收束；当别人要求立即定案时，尚未考察的可能性会显得格外诱人。不过，现实中的选择常常无法等待所有信息到齐。区分“会改变决定的新证据”和“只是让我更放心的额外信息”，能够帮助你知道什么时候该停止探索。','计划与开放并不是互相排斥的品质。你可以先确定当前阶段的目标，同时让实现目标的方法保持可调整；观察哪种安排让你更投入，会比从中点得分推断自己应该怎样生活更可靠。')+'同样值得留意的是，你在熟悉环境中自然表现出的样子，未必与面对评价时完全一致。把最近一次轻松投入的经历与一次明显受阻的经历放在一起比较，你会更容易分辨：哪些是长期偏好，哪些只是当时的精力、关系或任务要求带来的反应。';
 const workScene=pick(t,'例如，面对一个效果不佳的产品或流程，你可能先追问问题到底出在需求、设计还是执行，尝试把含混的评价转换成可以检验的假设。研究、编程、分析、工程或策略任务中，都可能包含这样的工作片段；吸引你的未必是某个职位名称，而是有机会深入理解问题，并看到自己的推理如何改变结果。','例如，面对一个效果不佳的产品或服务，你可能先留意使用它的人究竟遇到了什么困难，团队为什么没有理解彼此，或者现有安排牺牲了谁的需要。教育、设计、客户研究、组织协作等任务中，都可能包含这样的工作片段；吸引你的未必是某个职位名称，而是能看到自己的投入如何改善具体体验。','例如，面对一个效果不佳的项目，你可以分别观察自己更愿意研究问题原因、协调参与者，还是推动实际把事情做好并交出去。相同职位里也可能包含截然不同的任务组合，亲自体验这些部分，会比按字母挑选行业更有区分度。')+pick(j,'你可能还希望将这些发现整理成下次也能用的办法，减少团队下次遇到相似问题时的混乱。','如果任务允许尝试不同路径，你可能更愿意先做一个小实验，再根据结果调整，而不是一开始就规定全部过程。','明确任务的目的与边界后，再决定过程需要多少结构，会有助于把偏好落实到工作安排中。');
 const workTension=pick(e,'此外，频繁的互动虽然能让你得到反馈，也可能让一天被会议和即时消息切得很碎。如果思路总在回应别人的需求时被打断，原本享受的合作就可能变成持续的忙碌，却很少留下足够完整的成果。','此外，深入思考并不自动等于让别人理解你的贡献。如果你习惯等到方案足够完善才汇报，伙伴可能不知道你已经解决了哪些问题，也难以及时提供真正需要的信息。你不必变得健谈，但可以用简短的进展记录，让别人看见正在发生的工作。','此外，不论偏好独立还是共同推进，合作都需要让别人知道当前进度、尚未解决的问题和下一次同步的时间。')+'一个值得尝试的办法，是把理想工作拆成几项可以询问和验证的条件：一周有多少时间用于核心任务，谁决定先后顺序，反馈如何给出，临时要求是否经常打断安排。即使暂时不能更换岗位，也可以先争取一个较小的调整，例如固定专注时段、明确一次做到什么程度才算完成，或承担一个能检验兴趣的小项目。';
 const growthScene=pick(n,'学习新事物时，你可能会因为看见一个完整的新方向而很快投入，接着不断寻找更深入的材料。当知识之间开始连成一张网，理解本身会给你带来动力；但如果每次都从新的起点出发，你也可能积累了许多认识，却很少有机会确认自己能否在现实中使用它们。','学习新事物时，你可能更容易被清楚的练习、真实的示例和看得见的进步带动。当一个方法逐渐熟练，你会知道努力正在产生效果；但如果只反复练习已经擅长的部分，也可能很少碰到那些暂时生疏、却能够拓宽能力边界的任务。','学习新事物时，可以比较两种过程：先理解整体框架，再进入练习；或者先做一个具体任务，再补充原理。找到更适合当前阶段的顺序，会比勉强采用别人习惯的方法更有帮助。')+'你可以为一次学习安排一个明确的输出：解释给另一个人听、完成一个小作品，或处理一个以前会回避的问题。这样，成长就不只是一种“我应该变得更好”的期待，而会变成可以观察、调整并逐步积累的经验。';
 const growthTension=pick(t,'另一个需要练习的部分，是接受那些暂时无法被彻底分析的感受。你可能很快就能找出一件事情哪里不合理，却不容易立即说清自己为什么疲惫、失望或不愿继续。先承认这种感受存在，再考虑它传递了什么信息，能够让理性判断得到更多线索，而不是被迫承担全部问题。','另一个需要练习的部分，是分清愿意付出与害怕让人失望之间的差别。你可能很熟悉他人的期待，却较少认真询问自己是否有精力、是否真正赞同，或者这件事是否仍然值得投入。把这些问题放到决定之前，会让之后的付出更有选择感。','另一个需要练习的部分，是把感受、判断与行动区分开来。你可以对一件事感到不安，同时承认还没有足够证据判断结果；也可以认可别人的出发点，却选择一种更适合自己的做法。')+'当你准备尝试改变时，不妨把目标缩小到一周内能做到的程度，并提前想好什么现象代表有帮助。这样，即使尝试没有奏效，你也能得到关于方法的反馈，而不必把它解释为自己缺乏毅力或不适合成长。';
 const relationsScene=pick(n,'你可能会通过分享想法、讨论未来，或一起探索感兴趣的话题建立亲近感。一段能够不断提出新问题的谈话，会让你觉得彼此之间还有许多值得认识的地方。不过，有些人更习惯通过一起吃饭、完成一件小事或记住生活细节表达在意；他们未必接得住抽象讨论，却可能在实际行动里给出稳定的回应。','你可能会通过记住对方的习惯、兑现约定，或在对方需要时提供具体帮助表达在意。这些细节会让关系变得真实而可靠。不过，有些人更习惯通过语言、情绪分享或讨论未来确认连接；即使日常照顾已经十分周到，他们仍可能希望听到你如何理解这段关系。','建立亲近感的方式可以很多：分享想法、一起行动、倾听感受，或记住一件对方看重的小事。你可以留意自己最自然采用哪一种，也观察对方在哪一种回应中感到被理解。')+'表达方式的差异并不意味着一方更认真。与其等待对方自动读懂自己的用心，不如询问什么样的陪伴对彼此真正有帮助；这会让付出更容易被看见，也减少“我已经做了很多，你为什么还不明白”的失落。';
 const relationsTension=pick(a,'当发生分歧时，你或许能够较快恢复平常的状态，却需要留意对方是否也准备好了继续。有些事情对你而言已经说开，对方却仍需要时间确认伤害是否被理解；主动问一句“这件事还有什么让你放不下”，能够让修复更完整。','当发生分歧时，你可能反复思考对方的用词、语气和沉默，试图提前弄清关系是否已经改变。但如果缺少直接沟通，想象中的解释会越来越多，真实的信息却没有增加。把疑问缩小成一个可以回答的问题，会比反复回看细节更容易靠近事实。','当发生分歧时，可以先确认双方是否仍在讨论同一件事：你们是在核对事实、表达受伤，还是商量今后如何相处。不同的问题需要不同的回应，急着一次解决全部内容，反而容易让谈话失去重点。')+'修复也不只是一句道歉。它可能包括承认某种表达让对方难受、解释自己的真实意图，再约定下一次怎样处理相似情境。彼此愿意持续做出这些具体回应时，差异才更有机会成为可以协商的部分，而不是一再出现、却始终无人解释的距离。';
 return {traits:traits+traitsScene+'\n\n'+traitsDepth+traitsTension,work:work+workScene+'\n\n'+workDepth+workTension,growth:growth+growthScene+'\n\n'+growthDepth+growthTension,relations:relations+relationsScene+'\n\n'+relationsDepth+relationsTension};
}
export function narrativeText(result){const r=buildReport(result),summaries=chapterSummaries(result);return `\n\n${r.name}\n${r.tagline}\n`+[['traits','人格总结'],['work','职业道路总结'],['growth','个人成长总结'],['relations','人际关系总结']].map(([key,title])=>`\n${title}\n${summaries[key]}\n`).join('')+'\n'+r.selected.map(g=>`${g.axis} · ${g.title}\n${g.meaning}\n可能的优势：${g.strength}。${g.detail}\n留意：${g.risk}。${g.riskDetail}\n行动：${g.action}\n适合尝试的环境：${g.environment}\n关系建议：${g.relationship}`).join('\n\n')+'\n\n七天行动计划\n'+r.plan.map(p=>`${p.day} · ${p.title}\n${p.body}`).join('\n\n');}
